  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Chassepierre', 'Malebná vesnička nad břehem Semois, kterou si zamilovali malíři i pořadatelé slavného festivalu pouličního umění. Kostel sv. Martina s vesnicí na skalním ostrohu tvoří jeden z nejromantičtějších obrázků Gaume. Ideální první fotozastávka pár minut od startu.', 49.7108, 5.2536, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chassepierre.%20%C3%A9glise%20Saint-Martin.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Chassepierre.%20%C3%A9glise%20Saint-Martin.JPG"}'::text[], 0),
    (v_route, 'Château d''Herbeumont', 'Zřícenina středověkého hradu ze 13. století na hřebeni vysoko nad meandrem Semois. Krátká procházka od parkoviště vás odmění výhledem na dvojitou říční smyčku zvanou Tombeau du Chevalier. Přístupová silnice z údolí nahoru je řetěz utažených zatáček, které si říkají o druhý průjezd.', 49.7789, 5.2364, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20d''Herbeumont%203.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20d''Herbeumont%203.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/HerbeumontChateau201207061705.jpg"}'::text[], 1),
    (v_route, 'Tombeau du Géant (Botassart)', 'Obří meandr Semois obtékající zalesněný kopec, který připomíná obrův hrob – nejslavnější přírodní scenérie belgických Arden. Vyhlídka u Botassart je přímo u silnice, s lavičkami a dostatkem místa pro motorky. Nejpůsobivější je ráno, kdy se z údolí zvedá mlha.', 49.8069, 5.0286, 'https://commons.wikimedia.org/wiki/Special:FilePath/0%20Botassart%20-%20Tombeau%20du%20G%C3%A9ant%20(1).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/0%20Botassart%20-%20Tombeau%20du%20G%C3%A9ant%20(1).jpg"}'::text[], 2),
    (v_route, 'Rochehaut – vyhlídka na Frahan', 'Z terasy nad vesnicí Rochehaut se díváte přímo na podkovu Semois s vesničkou Frahan uprostřed – druhý ikonický pohled tohoto údolí. Na místě je parkoviště, panoramatické tabule i několik teras s kávou. Silnice z Rochehaut dolů k řece a zpět je oblíbená motorkářská hračka.', 49.8339, 5.0129, 'https://commons.wikimedia.org/wiki/Special:FilePath/Frahan%20viewed%20from%20Route%20d''Alle%20(DSCF5187-5197).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Frahan%20viewed%20from%20Route%20d''Alle%20(DSCF5187-5197).jpg"}'::text[], 3),
    (v_route, 'Restaurace: L''Auberge de la Ferme (Rochehaut)', 'Rodinný hotel s vyhlášenou restaurací přímo v Rochehaut, který staví na zvěřině, ardenské šunce a surovinách z vlastní farmy. Patří k nejlépe hodnoceným podnikům v celém údolí Semois a k obědu nabízí i jednodušší bistro menu. Rezervace se o víkendu vyplatí.', 49.8341, 5.0136, 'https://commons.wikimedia.org/wiki/Special:FilePath/Frahan%20viewed%20from%20Route%20d''Alle%20(DSCF5187-5197).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Frahan%20viewed%20from%20Route%20d''Alle%20(DSCF5187-5197).jpg"}'::text[], 4),
    (v_route, 'Laforêt – Pont de Claies', 'Laforêt patří mezi nejkrásnější vesnice Valonska a v létě tu přes Semois vede unikátní proutěný most Pont de Claies, který se každý rok staví znovu. Břidlicové domky a klid u řeky jsou příjemnou tečkou před návratem přes lesy zpět do Florenville. Mimo sezónu most nahrazuje brod – k vidění je od července do září.', 49.8617, 4.9394, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20de%20Claies,%20Lafor%C3%AAt.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20de%20Claies,%20Lafor%C3%AAt.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Spa – Pouhon Pierre le Grand', 'Hlavní minerální pramen lázeňského města Spa, pojmenovaný po caru Petru Velikém, který se tu léčil v roce 1717. Elegantní pavilon uprostřed města je symbolem lázní zapsaných na seznam UNESCO. Před startem ochutnejte železitou vodu a projděte si secesní kolonády.', 50.4925, 5.8631, 'https://commons.wikimedia.org/wiki/Special:FilePath/Spa%20Pouhon-Pierre-Le-Grand%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Spa%20Pouhon-Pierre-Le-Grand%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Spa%20Pouhon%20PLG%20R01.jpg"}'::text[], 0),
    (v_route, 'Lac de Warfaaz', 'Klidné jezero v lesích kousek nad Spa, obklíbené promenádou, loďkami a několika terasami u vody. Krátká odbočka hned na začátku okruhu, ideální na ranní kávu s výhledem na hladinu. Silnička kolem jezera pokračuje pěkným stoupáním do lesů směrem na Theux.', 50.5006, 5.8933, 'https://commons.wikimedia.org/wiki/Special:FilePath/Spa%20Lac%20Warfaaz%20R01.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Spa%20Lac%20Warfaaz%20R01.jpg"}'::text[], 1),
    (v_route, 'Château de Franchimont', 'Mohutná zřícenina hradu lutyšských knížat-biskupů nad městečkem Theux, přestavěná v 16. století na dělostřeleckou pevnost. Z hradeb je krásný výhled do údolí Hoëgne a expozice ukazuje, jak se hrad bránil. Parkoviště je hned u vstupu, prohlídka zabere příjemnou hodinku.', 50.5333, 5.8203, 'https://commons.wikimedia.org/wiki/Special:FilePath/0%20Theux%20-%20Ch%C3%A2teau%20de%20Franchimont%20(3).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/0%20Theux%20-%20Ch%C3%A2teau%20de%20Franchimont%20(3).jpg"}'::text[], 2),
    (v_route, 'Grottes de Remouchamps', 'Jeskynní systém na řece Rubicon, kde vás čeká nejdelší podzemní plavba na loďce v Evropě – téměř kilometr tichého klouzání pod krápníky. Prohlídka trvá zhruba hodinu a čtvrt a je skvělým zpestřením motorkářského dne. Vstup je přímo u hlavní silnice v Remouchamps, kavárna přes ulici.', 50.4794, 5.7136, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grottes%20de%20Remouchamps%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grottes%20de%20Remouchamps%2001.JPG"}'::text[], 3),
    (v_route, 'Stavelot – opatství', 'Bývalé knížecí opatství založené už v 7. století dnes ukrývá tři muzea, mimo jiné slavné muzeum okruhu Spa-Francorchamps s historickými závodními stroji. Náměstíčko před opatstvím lemují kavárny a v místním pivovaru se vaří klášterní pivo. Cesta ze Stavelot zpět do Spa lesem přes Malchamps je krásná svižná pasáž.', 50.3947, 5.9308, 'https://commons.wikimedia.org/wiki/Special:FilePath/Abbaye%20de%20Stavelot%2003.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Abbaye%20de%20Stavelot%2003.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Abdij%20van%20Stavelot.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Brasserie du Grand Maur (Spa)', 'Stylová brasserie v historickém domě v centru Spa s poctivou valonskou kuchyní – ardenskou šunkou, masem na pivu a sezónními specialitami. Hosté ji dlouhodobě řadí mezi nejlepší podniky ve městě. Perfektní závěrečná večeře po okruhu, pár kroků od pramene Pouhon.', 50.4930, 5.8654, 'https://commons.wikimedia.org/wiki/Special:FilePath/Spa%20Pouhon%20PLG%20R01.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Spa%20Pouhon%20PLG%20R01.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Malmedy – katedrála', 'Barokní dvouvěžová katedrála sv. Petra, Pavla a Quirina je dominantou příjemného městečka na okraji Hautes Fagnes. Malmedy je známé karnevalem, papírenskou historií a dobrými kavárnami na náměstí – ideální místo na start a tankování. Odtud silnice stoupá rovnou do vřesovišť.', 50.4262, 6.0269, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cath%C3%A9drale%20de%20Malmedy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cath%C3%A9drale%20de%20Malmedy.jpg"}'::text[], 0),
    (v_route, 'Baraque Michel', 'Historický zájezdní hostinec z roku 1811 uprostřed pustiny Hautes Fagnes, kdysi záchrana pro poutníky bloudící v mlze a sněhu. Dnes oblíbená motorkářská zastávka na kávu a palačinky, od které vedou povalové chodníky do rašelinišť. Kaple Fischbach hned vedle připomíná zachráněné poutníky.', 50.5203, 6.0631, 'https://commons.wikimedia.org/wiki/Special:FilePath/Baraque%20Michel,%20restaurant%20Baraque%20Michel%20foto3%202011-06-04%2013.19.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Baraque%20Michel,%20restaurant%20Baraque%20Michel%20foto3%202011-06-04%2013.19.JPG"}'::text[], 1),
    (v_route, 'Signal de Botrange', 'Nejvyšší bod Belgie (694 m) s kamennou vyhlídkovou věží a rozlehlým výhledem přes vřesoviště až do Německa. Přímo u silnice je velké parkoviště, restaurace a návštěvnické centrum parku. Povinná fotka u cedule s nadmořskou výškou – výš už se v Belgii na motorce nedostanete.', 50.5017, 6.0939, 'https://commons.wikimedia.org/wiki/Special:FilePath/Signal%20de%20Botrange%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Signal%20de%20Botrange%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Belgium,%20Botrange,%20Communication%20tower.JPG"}'::text[], 2),
    (v_route, 'Barrage de la Vesdre (Eupen)', 'Přehrada na říčce Vesdre nad Eupenem zásobuje pitnou vodou celý východ Belgie a její kamenná hráz s věžemi patří k největším v zemi. Po koruně hráze se dá projít a z vyhlídky je pěkný pohled na jezero sevřené smrkovými lesy. Příjezd lesem od Ternell je krásná plynulá pasáž.', 50.5989, 6.0761, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wesertalsperre%20Eupen.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wesertalsperre%20Eupen.JPG"}'::text[], 3),
    (v_route, 'Lac de Robertville', 'Přehradní jezero na řece Warche s průzračnou vodou, pláží a půjčovnou loděk, obklopené loukami a lesy. V létě láká ke koupání, po zbytek roku ke klidné zastávce s výhledem na hladinu. Silnice kolem jezera a dolů do údolí Warche nabízí sled pěkných zatáček.', 50.4569, 6.1114, 'https://commons.wikimedia.org/wiki/Special:FilePath/Robertville%20JPG01.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Robertville%20JPG01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20de%20Robertville%20bei%20Outrewarche.jpg"}'::text[], 4),
    (v_route, 'Château de Reinhardstein', 'Nejvýše položený hrad Belgie se tyčí na skále v divokém údolí Warche pod hrází Robertville. Věrně obnovená středověká pevnost s rytířskými sály a zbrojnicí vypadá jako z pohádky; k hradu se jde 15 minut pěšky lesem. Kousek pod hradem je nejvyšší vodopád země.', 50.4433, 6.1114, 'https://commons.wikimedia.org/wiki/Special:FilePath/Robertville%20-%20Ch%C3%A2teau%20de%20Reinhardstein.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Robertville%20-%20Ch%C3%A2teau%20de%20Reinhardstein.jpg"}'::text[], 5),
    (v_route, 'Restaurace: Plein Vent (Bévercé u Malmedy)', 'Restaurace s panoramatickou terasou na silnici ze Spa do Malmedy, odkud se díváte přes celé údolí až na hřebeny Arden. Vyhlášená je poctivou regionální kuchyní a jedním z nejhezčích výhledů, u kterých se dá v Belgii obědvat. Skvělé zakončení okruhu před sjezdem do Malmedy.', 50.4489, 6.0339, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cath%C3%A9drale%20de%20Malmedy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cath%C3%A9drale%20de%20Malmedy.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Citadela Namur', 'Rozlehlá pevnost nad soutokem Mázy a Sambry, kterou Napoleon nazval termitištěm Evropy kvůli kilometrům podzemních chodeb. Na vrchol vede krásná okresní silnička Route Merveilleuse plná vlásenek – z hradeb je nejhezčí výhled na hlavní město Valonska. Ideální rozjezd celého okruhu.', 50.4592, 4.8631, 'https://commons.wikimedia.org/wiki/Special:FilePath/La%20Citadelle%20de%20Namur.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/La%20Citadelle%20de%20Namur.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Namur%20Citadelle%2007.JPG"}'::text[], 0),
    (v_route, 'Jardins d''Annevoie', 'Vodní zahrady z 18. století, kde desítky fontán, kaskád a kanálů fungují dodnes bez jediného čerpadla – jen díky důmyslnému spádu pramenů. Procházka mezi vodotrysky a starými buky zabere hodinku a krásně rozbije jízdu podél řeky. Parkování přímo u vstupu.', 50.3444, 4.8506, 'https://commons.wikimedia.org/wiki/Special:FilePath/Les%20jardins%20d''Annevoie%20-%20Le%20petit%20canal.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Les%20jardins%20d''Annevoie%20-%20Le%20petit%20canal.JPG"}'::text[], 1),
    (v_route, 'Dinant – Collégiale a citadela', 'Nejfotogeničtější město na Máze: cibulová věž gotické kolegiáty Notre-Dame přilepené ke skále, nad ní citadela a před ní řada barevných domů zrcadlících se v řece. Nahoru vede 408 schodů nebo lanovka a město je plné odkazů na rodáka Adolpha Saxe, vynálezce saxofonu. Motorku zaparkujete na nábřeží.', 50.2606, 4.9122, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dinant%20Coll%C3%A9giale%20Notre%20Dame%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dinant%20Coll%C3%A9giale%20Notre%20Dame%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Church%20La%20Col%C3%A9giale%20in%20Dinant.JPG"}'::text[], 2),
    (v_route, 'Restaurace: La Broche (Dinant)', 'Útulná restaurace v uličce u kolegiáty patří dlouhodobě k nejlépe hodnoceným v Dinantu. Francouzská kuchyně ze sezónních surovin, rozumné polední menu a ochotná obsluha – přesně to, co po dopoledni v sedle potřebujete. V sezóně doporučujeme rezervaci.', 50.2617, 4.9114, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dinant%20Coll%C3%A9giale%20Notre%20Dame%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dinant%20Coll%C3%A9giale%20Notre%20Dame%2001.JPG"}'::text[], 3),
    (v_route, 'Rocher Bayard', 'Čtyřicetimetrová skalní jehla na břehu Mázy, kterou podle legendy rozťal kopytem kouzelný kůň Bayard prchající před Karlem Velikým. Silnice projíždí přímo úzkou soutěskou mezi jehlou a masivem – zpomalte a vychutnejte si ten průjezd. Hned za skálou je odstavný pruh na fotku.', 50.2508, 4.9086, 'https://commons.wikimedia.org/wiki/Special:FilePath/RocherBayardDinant.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/RocherBayardDinant.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Dinant,%20le%20rocher%20Bayard%20foto13%202012-06-30%2014.16.JPG"}'::text[], 4),
    (v_route, 'Château de Freÿr', 'Renesanční zámek s barokními terasovými zahradami přímo na břehu Mázy, naproti slavným lezeckým stěnám Rochers de Freÿr. Kdysi tu odpočívala i Marie Terezie; oranžerie ukrývá tři sta let staré pomerančovníky. Jeden z nejromantičtějších pohledů celého údolí.', 50.2222, 4.8894, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20de%20Fre%C3%BFr%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20de%20Fre%C3%BFr%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Freyr%20R01.jpg"}'::text[], 5),
    (v_route, 'Château de Vêves', 'Pohádkový hrad s pěti špičatými věžemi u vesnice Celles, jedné z nejkrásnějších vesnic Valonska. Patří k nejzachovalejším ukázkám středověké hradní architektury v Belgii a interiéry obývá stejný rod už přes 800 let. Silničky v okolí Celles jsou příjemným zakončením před návratem do Namuru.', 50.2258, 5.0072, 'https://commons.wikimedia.org/wiki/Special:FilePath/Celles%20(Houyet)%20-%20Ch%C3%A2teau%20de%20V%C3%AAves%20(1).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Celles%20(Houyet)%20-%20Ch%C3%A2teau%20de%20V%C3%AAves%20(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20de%20V%C3%AAves%20Belgique%2026.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Brugy – Rozenhoedkaai a Belfort', 'Nejslavnější pohled Belgie: nábřeží Rozenhoedkaai, kde se středověké domy a 83 metrů vysoká zvonice Belfort zrcadlí v kanálu. Historické centrum je na seznamu UNESCO a nejlépe se projde pěšky – motorku nechte na parkovišti u okruhu. Ranní Brugy před příjezdem autobusů jsou kouzelné.', 51.2081, 3.2270, 'https://commons.wikimedia.org/wiki/Special:FilePath/Brugge-CanalRozenhoedkaai.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Brugge-CanalRozenhoedkaai.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Rozenhoedkaai%20Brugge.jpg"}'::text[], 0),
    (v_route, 'Pivovar De Halve Maan (Brugy)', 'Rodinný pivovar v centru Brug, kde se od roku 1856 vaří slavné pivo Brugse Zot a Straffe Hendrik. Prohlídka končí na střešní terase s výhledem na město a v restauraci vaří poctivou vlámskou kuchyni – karbonádu na pivu nebo severomořské ryby. Pro řidiče mají nealko variantu, plnou verzi si schovejte na večer.', 51.2029, 3.2245, 'https://commons.wikimedia.org/wiki/Special:FilePath/Brauerei%20De%20Halve%20Maan%20(Brouwerij%20De%20Halve%20Maan)%20in%20Br%C3%BCgge,%20Belgien%20-%20Eingangsbereich.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Brauerei%20De%20Halve%20Maan%20(Brouwerij%20De%20Halve%20Maan)%20in%20Br%C3%BCgge,%20Belgien%20-%20Eingangsbereich.jpg"}'::text[], 1),
    (v_route, 'Damme', 'Bývalý hanzovní přístav Brug, dnes ospalé městečko s gotickou radnicí, větrným mlýnem a knihkupectvími. Vede sem jedna z nejkrásnějších silniček Flander – alej podél kanálu Damse Vaart lemovaná topoly. Ideální krátká zastávka na kávu na náměstí.', 51.2511, 3.2814, 'https://commons.wikimedia.org/wiki/Special:FilePath/Damme%20town%20hall,%20Belgium.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Damme%20town%20hall,%20Belgium.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Book%20market%20in%20front%20of%20the%20Damme%20town%20hall,%20Belgium.jpg"}'::text[], 2),
    (v_route, 'Přírodní rezervace Zwin', 'Slaniska a laguny při ústí bývalého mořského ramene, kterému se říká mezinárodní letiště ptáků – zastávka tisíců čápů, rybáků a bahňáků. Vyhlídkové lávky vedou přímo mezi kanály zaplavovanými přílivem. Nezapomeňte na dalekohled, na jaře a na podzim je tu ptačí špička.', 51.3583, 3.3592, 'https://commons.wikimedia.org/wiki/Special:FilePath/20110522%20Zwin%20(7).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/20110522%20Zwin%20(7).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/20110522%20Zwin%20(32).jpg"}'::text[], 3),
    (v_route, 'De Haan – belle époque', 'Nejzachovalejší lázeňské letovisko belgického pobřeží, kde je celá čtvrť vil z přelomu století památkově chráněná – včetně půvabné tramvajové zastávky, u níž kdysi vystupoval Albert Einstein. Široká pláž je pár kroků od centra. Projížďka mezi vilami je jako cesta časem o sto let zpět.', 51.2725, 3.0347, 'https://commons.wikimedia.org/wiki/Special:FilePath/De%20Haan%20tramstation.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/De%20Haan%20tramstation.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/De%20Haan%20Hotel%20Belle%20Epoque%20R01.jpg"}'::text[], 4),
    (v_route, 'Oostende – Albert I. promenáda', 'Královna belgických plážových měst s širokou promenádou, přístavem a nejlepšími stánky s čerstvými rybami a garnáty na celém pobřeží. Projděte se po molu, dejte si kornout hranolek nebo rybí polévku ve Visserskaai. Odtud se vracíte poldery zpět do Brug.', 51.2326, 2.9126, 'https://commons.wikimedia.org/wiki/Special:FilePath/Oostende%20Albert%20I%20Promenade%20R01.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Oostende%20Albert%20I%20Promenade%20R01.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Gravensteen (Gent)', 'Vodní hrad flanderských hrabat z 12. století přímo uprostřed Gentu, s hradbami, věžemi a vodním příkopem jako z učebnice. Z ochozu je nejlepší výhled na věže a kanály města, které večer krásně nasvěcují. Před odjezdem stihněte aspoň krátkou procházku po nábřeží Graslei.', 51.0573, 3.7208, 'https://commons.wikimedia.org/wiki/Special:FilePath/The%20Gravensteen%20Castle%20-%20Ghent,%20Belgium%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Gravensteen%20Castle%20-%20Ghent,%20Belgium%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gravensteen,%20Ghent%20(DSCF0191).jpg"}'::text[], 0),
    (v_route, 'Oudenaarde – radnice', 'Pozdně gotická radnice se zvonicí na seznamu UNESCO je klenotem městečka, které žije cyklistikou a pivem – sídlí tu muzeum závodu Kolem Flander i pivovar hnědých piv Liefmans. Náměstí lemují kavárny s terasami, ideální na pauzu před útokem na okolní kopce.', 50.8442, 3.6072, 'https://commons.wikimedia.org/wiki/Special:FilePath/Oudenaarde%20(East%20Flanders,%20Belgium)%20late%20Gothic%20town%20hall%20and%20belfry%20tower.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Oudenaarde%20(East%20Flanders,%20Belgium)%20late%20Gothic%20town%20hall%20and%20belfry%20tower.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Monument%20Markt%201%20(stadhuis)%20Oudenaarde.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Margaretha''s (Oudenaarde)', 'Elegantní restaurace přímo na náměstí v Oudenaarde s výhledem na radnici, vyhlášená moderní flanderskou kuchyní z lokálních surovin a skvělou kartou belgických piv. Patří k nejlépe hodnoceným podnikům ve městě. Polední menu je výhodné a rychlé, přesně do motorkářského dne.', 50.8444, 3.6069, 'https://commons.wikimedia.org/wiki/Special:FilePath/Monument%20Markt%201%20(stadhuis)%20Oudenaarde.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Monument%20Markt%201%20(stadhuis)%20Oudenaarde.jpg"}'::text[], 2),
    (v_route, 'Koppenberg', 'Nejobávanější stěna cyklistických Flander: 600 metrů kostek se sklonem až 22 procent v úvozu mezi stromy. Na motorce vyžaduje plynulý průjezd na jedničku a pevnou ruku, za mokra kostky raději objeďte. Nahoře se otevře výhled na zvlněný kraj, kterému se právem říká Flanderské Ardeny.', 50.8256, 3.5744, 'https://commons.wikimedia.org/wiki/Special:FilePath/Koppenberg%20cobbles.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Koppenberg%20cobbles.jpg"}'::text[], 3),
    (v_route, 'Oude Kwaremont', 'Nejdelší kostkované stoupání Flander vede kolem kostelíka sv. Amanda do vesničky Kwaremont, kde závod Kolem Flander každé jaro rozhoduje o vítězi. V místní hospodě čepují stejnojmenné pivo a stěny zdobí fotky legend. Výhledy z hřebene stojí za krátkou pěší procházku.', 50.7789, 3.5219, 'https://commons.wikimedia.org/wiki/Special:FilePath/De%20Sint-Amanduskerk%20gezien%20van%20op%20de%20Oude%20Kwaremont%20-%202020.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/De%20Sint-Amanduskerk%20gezien%20van%20op%20de%20Oude%20Kwaremont%20-%202020.jpg"}'::text[], 4),
    (v_route, 'Muur van Geraardsbergen (Kapelmuur)', 'Legendární kostkovaná zeď stoupající z náměstí v Geraardsbergen ke kapli Panny Marie na vrcholu Oudenberg. Z vrcholu je kruhový výhled na Flanderské Ardeny a Pajottenland; dole ve městě ochutnejte místní specialitu mattentaart. Důstojná tečka za okruhem před návratem do Gentu.', 50.7658, 3.8811, 'https://commons.wikimedia.org/wiki/Special:FilePath/Muur%20van%20Geraardsbergen%20116.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Muur%20van%20Geraardsbergen%20116.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Leuven – radnice', 'Pozdně gotická radnice na Grote Markt je pokrytá 236 sochami a považuje se za nejzdobnější na světě. Univerzitní Leuven žije studenty a pivem – na Oude Markt, nejdelším baru Evropy, sídlí desítky hospod a nedaleko stojí pivovar Stella Artois. Ranní káva na náměstí je skvělý start dne.', 50.8792, 4.7009, 'https://commons.wikimedia.org/wiki/Special:FilePath/Leuven,%20stadhuis.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Leuven,%20stadhuis.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stadhuis%20Leuven.JPG"}'::text[], 0),
    (v_route, 'Opatství Park (Heverlee)', 'Premonstrátské opatství ze 12. století na jižním okraji Leuvenu, obklopené rybníky, sady a poli – jeden z nejzachovalejších klášterních areálů Beneluxu. Sídlí tu muzeum náboženského umění PARCUM a kolem vodních ploch vede krásná okružní cesta. Klidná zastávka pár minut od centra.', 50.8631, 4.7181, 'https://commons.wikimedia.org/wiki/Special:FilePath/Abdij%20van%20''t%20Park.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Abdij%20van%20''t%20Park.JPG"}'::text[], 1),
    (v_route, 'Bazilika Scherpenheuvel', 'Nejvýznamnější poutní místo Belgie: raně barokní bazilika s hvězdami posetou kopulí stojí na kopci, kam už staletí míří poutníci za sochou Panny Marie. Sedmiúhelníkový půdorys a výhled z návrší dělají ze zastávky zážitek i pro nevěřící. Kolem baziliky voní stánky s poutními oplatkami.', 50.9800, 4.9772, 'https://commons.wikimedia.org/wiki/Special:FilePath/Onze-Lieve-Vrouwebasiliek%20in%20Scherpenheuvel.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Onze-Lieve-Vrouwebasiliek%20in%20Scherpenheuvel.jpg"}'::text[], 2),
    (v_route, 'Opatství Averbode', 'Bílé premonstrátské opatství ze 12. století na rozhraní tří provincií, ukryté v borových lesích Kempenu. Barokní kostel patří k nejkrásnějším ve Flandrech a v klášterním obchodě koupíte pivo Averbode, sýry i chleba z vlastní pekárny. Terasa u brány je oblíbenou zastávkou motorkářů i cyklistů.', 51.0236, 4.9808, 'https://commons.wikimedia.org/wiki/Special:FilePath/Averbode%20Abdij%20R01.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Averbode%20Abdij%20R01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Abdij%20Averbode%20-%20Belgi%C3%AB.jpg"}'::text[], 3),
    (v_route, 'Diest – bekináž', 'Bekinážní dvůr z 13. století v Diestu je jedním z nejzachovalejších v Belgii a patří na seznam UNESCO – brána s Madonou, brukvové uličky a domky s bílenými fasádami působí, jako by se tu zastavil čas. Městečko nabízí i pěkné náměstí a pivo Gildenbier. Klidná tečka před návratem do Leuvenu.', 50.9886, 5.0508, 'https://commons.wikimedia.org/wiki/Special:FilePath/Diest-begijnhof.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Diest-begijnhof.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Begijnhof%20Diest%20-%20Kerkstraat.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Zarza (Leuven)', 'Moderní bistro-restaurace kousek od radnice v Leuvenu, která patří k nejlépe hodnoceným podnikům města. Otevřená kuchyně servíruje kreativní evropské menu ze sezónních surovin za férové ceny. Ideální večeře po okruhu; večer bývá plno, rezervujte předem.', 50.8781, 4.7031, 'https://commons.wikimedia.org/wiki/Special:FilePath/Stadhuis%20Leuven.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Stadhuis%20Leuven.JPG"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Huy – citadela a kolegiáta', 'Nad městem Huy se z vápencové skály zvedá pevnost z roku 1818 a pod ní gotická kolegiáta Notre-Dame se slavnou rozetou Rondia. Na citadelu vyjedete lanovkou nebo vystoupáte pěšky – výhled na údolí Mázy je nejlepší v okolí. Náměstí s fontánou Li Bassinia je příjemné na kávu.', 50.5186, 5.2372, 'https://commons.wikimedia.org/wiki/Special:FilePath/Citadelle%20de%20Huy%20006.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Citadelle%20de%20Huy%20006.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Coll%C3%A9giale%20Notre-Dame,%20Huy-1130.jpg"}'::text[], 0),
    (v_route, 'Restaurace: Li Cwerneu (Huy)', 'Drobná gastronomická restaurace v historickém domku přímo na Grand-Place v Huy, oceňovaná za kreativní valonskou kuchyni ze surovin od okolních farmářů. Patří k nejlépe hodnoceným podnikům v kraji; polední menu je překvapivě dostupné. Ideální posila před zvlněnými silničkami Condroz.', 50.5178, 5.2394, 'https://commons.wikimedia.org/wiki/Special:FilePath/Coll%C3%A9giale%20Notre-Dame,%20Huy-1130.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Coll%C3%A9giale%20Notre-Dame,%20Huy-1130.jpg"}'::text[], 1),
    (v_route, 'Château de Jehay', 'Renesanční vodní zámek s nezaměnitelnou šachovnicovou fasádou z bílého a hnědého kamene, obklopený vodním příkopem a zahradami se sochami. Patří provincii Lutych a v sezóně se otevírá veřejnosti. Krátká odbočka z údolí Mázy, která stojí za každý kilometr.', 50.5644, 5.2914, 'https://commons.wikimedia.org/wiki/Special:FilePath/0%20Jehay%20-%20Ch%C3%A2teau%20(1).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/0%20Jehay%20-%20Ch%C3%A2teau%20(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20de%20Jehay.JPG"}'::text[], 2),
    (v_route, 'Château de Modave', 'Barokní zámek na šedesátimetrové skále nad údolím Hoyoux, s bohatými štukovými interiéry a výhledem, který patří k nejhezčím ve Valonsku. Právě zde vzniklo vodní kolo, které později pohánělo fontány ve Versailles. Údolí Hoyoux pod zámkem je jedna z nejhezčích motorkářských silniček kraje.', 50.4453, 5.2958, 'https://commons.wikimedia.org/wiki/Special:FilePath/Modave-Ch%C3%A2teau%20de%20Modave%20(4).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Modave-Ch%C3%A2teau%20de%20Modave%20(4).jpg"}'::text[], 3),
    (v_route, 'Crupet – donjon', 'Vesnička Crupet patří mezi nejkrásnější vesnice Valonska a její středověká obytná věž obklopená vodním příkopem je jako z ilustrované kroniky. Kamenné domky, jeskyně sv. Antonína a hospůdka s místním pivem zvou k procházce. Silničky v okolí se krásně kroutí údolími potoků Bocq a Crupet.', 50.3494, 4.9528, 'https://commons.wikimedia.org/wiki/Special:FilePath/Crupet%20Castle%20donjon%2002.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Crupet%20Castle%20donjon%2002.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Crupet%20Castle%20donjon%2003.JPG"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Chiny – brána Semois', 'Kamenná vesnice na horním toku Semois, odkud řeka vstupuje do hlubokých ardenských lesů. V létě odsud vyplouvají tradiční pramice s převozníky do Lacuisine – nejromantičtější způsob, jak poznat řeku. Most a nábřeží jsou příjemnou první zastávkou okruhu.', 49.7369, 5.3411, 'https://commons.wikimedia.org/wiki/Special:FilePath/P1090022%20Chiny.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/P1090022%20Chiny.JPG"}'::text[], 0),
    (v_route, 'Opatství Orval', 'Trapistické opatství v zeleném údolí, kde se vaří legendární pivo Orval a zraje stejnojmenný sýr. Prohlédnout si můžete rozsáhlé středověké ruiny se studánkou Mathildy, jejíž legenda o navráceném prstenu zdobí každou lahev. Nový klášter slouží mnichům, obchod u brány prodává pivo i sýr.', 49.6389, 5.3494, 'https://commons.wikimedia.org/wiki/Special:FilePath/Abbaye%20d''Orval%20-%20Ruins%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Abbaye%20d''Orval%20-%20Ruins%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Abdij%20van%20Orval.jpg"}'::text[], 1),
    (v_route, 'Restaurace: À l''Ange Gardien (Orval)', 'Hostinec u brány opatství Orval, jediné místo na světě, kde se dá ochutnat vzácný Orval Vert – mladší, slabší verze klášterního piva čepovaná jen zde. K tomu poctivá venkovská kuchyně se sýrem z opatství a paštikami z Gaume. Terasa s výhledem do lesů je v sezóně plná motorkářů.', 49.6394, 5.3486, 'https://commons.wikimedia.org/wiki/Special:FilePath/BE-LX-Orval%20Abbaye%20hostellerie.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/BE-LX-Orval%20Abbaye%20hostellerie.JPG"}'::text[], 2),
    (v_route, 'Torgny', 'Nejjižnější vesnice Belgie a členka klubu nejkrásnějších vesnic Valonska: okrové kamenné domy s prejzovými střechami, jižní stráň s vinicí Clos de l''Epinette a mikroklima, ve kterém rostou i ještěrky a orchideje. Působí spíš jako Burgundsko než Belgie. Projděte se vinicí a ochutnejte místní víno.', 49.5064, 5.4772, 'https://commons.wikimedia.org/wiki/Special:FilePath/Torgny%20-%20Clos%20de%20l''Epinette.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Torgny%20-%20Clos%20de%20l''Epinette.jpg"}'::text[], 3),
    (v_route, 'Montquintin – zřícenina', 'Zřícenina hradu z 12. století na jednom z nejvyšších kopců Gaume, s výhledem přes údolí Tonu až do Francie. U hradu stojí románský kostelík a muzeum venkovského života ve staré faře. Silnička nahoru je úzká a strmá – přesně taková, jaké máme rádi.', 49.5300, 5.4750, 'https://commons.wikimedia.org/wiki/Special:FilePath/Montquintin%20JPG00.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Montquintin%20JPG00.JPG"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Houffalize', 'Městečko v hlubokém údolí Ourthe, přezdívané srdce Arden, s tankem Panther na náměstí jako připomínkou bitvy v Ardenách. Dnes je Houffalize hlavně rájem horských kol a motorek – kavárny na náměstí jsou ideální na ranní kávu před startem. Sjezd do města a výjezd ven jsou samy o sobě pěkné serpentiny.', 50.1325, 5.7897, 'https://commons.wikimedia.org/wiki/Special:FilePath/Houffalize%200011.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Houffalize%200011.JPG"}'::text[], 0),
    (v_route, 'Pivovar Achouffe (La Chouffe)', 'Kultovní pivovar v údolíčku u Achouffe, jehož pivo se skřítkem v červené čepici zná celý svět. Návštěvnické centrum nabízí prohlídky s ochutnávkou a obchod se vším od piva po ponožky se skřítkem. Řidiči si odvezou lahve na večer – nebo nealko verzi Chouffe 0,4 %.', 50.1614, 5.7758, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20van%20Achouffe.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20van%20Achouffe.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Chouffe-Zwerg%202014.JPG"}'::text[], 1),
    (v_route, 'Restaurace: La Petite Fontaine (Achouffe)', 'Vyhlášená hospůdka pár kroků od pivovaru v Achouffe, kde vaří ardenskou klasiku – zvěřinu, pstruhy a slavné pivní tlačenky – a čepují celou rodinu piv Chouffe. Mezi motorkáři jde o jednu z nejoblíbenějších zastávek v Ardenách, o víkendech počítejte s plnou terasou.', 50.1611, 5.7761, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20van%20Achouffe.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20van%20Achouffe.JPG"}'::text[], 2),
    (v_route, 'Baraque de Fraiture', 'Třetí nejvyšší bod Belgie (652 m) na náhorní plošině mezi Vielsalm a La Roche, v zimě lyžařské středisko, po zbytek roku křižovatka výletních tras s výhledy přes ardenské hřebeny. U silnice stojí památník bitvy v Ardenách s houfnicí. Hřebenová silnice N89 odsud dolů je rychlá a plynulá radost.', 50.2489, 5.7364, 'https://commons.wikimedia.org/wiki/Special:FilePath/Skipiste%20Baraque%20Fraiture.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Skipiste%20Baraque%20Fraiture.JPG"}'::text[], 3),
    (v_route, 'Le Hérou (Nadrin)', 'Skalnatý ostroh nad nejdivočejším úsekem Ourthe, kde řeka kreslí šest meandrů hluboko v lesích – podle mnohých nejkrásnější přírodní vyhlídka Arden. Od parkoviště u Nadrin je to krátká procházka k belvedéru s kruhovým rozhledem. Silnička z Nadrin dolů k řece je úzká, strmá a zábavná.', 50.1592, 5.6733, 'https://commons.wikimedia.org/wiki/Special:FilePath/Le%20Herou01.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Le%20Herou01.jpg"}'::text[], 4),
    (v_route, 'Barrage de Nisramont', 'Hráz na Ourthe kousek pod soutokem obou pramenných řek vytváří klidné jezero sevřené zalesněnými svahy. Po koruně hráze se dá projít a kolem jezera vede okružní stezka s lávkami nad hladinou. Tichá tečka okruhu před posledními kilometry zpět do Houffalize.', 50.1300, 5.6903, 'https://commons.wikimedia.org/wiki/Special:FilePath/0%20Nisramont%20-%20Barrage%20(1).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/0%20Nisramont%20-%20Barrage%20(1).JPG"}'::text[], 5);
