-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — BELGIE 2026 (10 tras)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Údolí Semois – Rochehaut a Tombeau du Géant
  delete from public.routes where name = 'Údolí Semois – Rochehaut a Tombeau du Géant' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Údolí Semois – Rochehaut a Tombeau du Géant', 'Okruh nejkrásnějším říčním údolím Belgie sleduje divoké meandry Semois po úzkých okreskách, které se vlní mezi lesy, tabákovými vesničkami a skalními vyhlídkami. Z Florenville projedete přes malířské Chassepierre a zříceninu Herbeumont k legendárnímu meandru Tombeau du Géant a vyhlídkám u Rochehaut, odkud se otevírá jeden z nejfotografovanějších pohledů celé země. Serpentiny mezi Bouillonem a Vresse jsou pastvou pro motorku i oči, ale silnice jsou úzké a v lese často vlhké, s listím a mechem v zatáčkách. Nejlépe si trasu užijete od května do října, ráno navíc s mlhami nad řekou. Počítejte s pomalejším tempem a nabitou kartou ve foťáku; tankujte ve Florenville nebo Bouillonu.', 'loop', 120, 210, 'medium',
     '[{"lat": 49.6997, "lng": 5.3062, "label": "Start: Florenville"}, {"lat": 49.7108, "lng": 5.2536, "label": "Chassepierre"}, {"lat": 49.7789, "lng": 5.2364, "label": "Herbeumont"}, {"lat": 49.8069, "lng": 5.0286, "label": "Botassart – Tombeau du Géant"}, {"lat": 49.8339, "lng": 5.0129, "label": "Rochehaut"}, {"lat": 49.8747, "lng": 4.9345, "label": "Vresse-sur-Semois"}, {"lat": 49.6997, "lng": 5.3062, "label": "Cíl: Florenville"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.6997,5.3062&destination=49.6997,5.3062&travelmode=driving&waypoints=49.7108,5.2536%7C49.7789,5.2364%7C49.8069,5.0286%7C49.8339,5.0129%7C49.8747,4.9345', 'https://commons.wikimedia.org/wiki/Special:FilePath/0%20Botassart%20-%20Tombeau%20du%20G%C3%A9ant%20(1).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Chassepierre.%20%C3%A9glise%20Saint-Martin.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20d''Herbeumont%203.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/0%20Botassart%20-%20Tombeau%20du%20G%C3%A9ant%20(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Frahan%20viewed%20from%20Route%20d''Alle%20(DSCF5187-5197).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Frahan%20viewed%20from%20Route%20d''Alle%20(DSCF5187-5197).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20de%20Claies,%20Lafor%C3%AAt.jpg"}'::text[], '{"Chassepierre","Château d''Herbeumont","Tombeau du Géant (Botassart)","Rochehaut – vyhlídka na Frahan","Restaurace: L''Auberge de la Ferme (Rochehaut)","Laforêt – Pont de Claies"}'::text[], '{"BE"}'::text[], false, 3110, 'approved');

  -- Okolí Spa – Franchimont, Remouchamps a Stavelot
  delete from public.routes where name = 'Okolí Spa – Franchimont, Remouchamps a Stavelot' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Okolí Spa – Franchimont, Remouchamps a Stavelot', 'Kompaktní okruh kolem lázeňského města Spa, které dalo jméno lázním po celém světě a je zapsané na seznamu UNESCO. Trasa spojuje jezero Warfaaz, mohutnou pevnost Franchimont nad Theux, podzemní plavbu v jeskyních Remouchamps a tisícileté opatství ve Stavelot. Silnice v zalesněných údolích Hoëgne a Amblève jsou skvěle asfaltované a plné plynulých zatáček, stoupání od Remouchamps ke Spa patří k nejhezčím v kraji. Vhodné i pro méně zkušené jezdce; pozor jen na cyklisty, kterých tu o víkendech jezdí spousta. Ideální od jara do podzimu, v okolí Spa počítejte s častějšími přeháňkami.', 'loop', 95, 150, 'easy',
     '[{"lat": 50.4922, "lng": 5.8628, "label": "Start: Spa"}, {"lat": 50.5006, "lng": 5.8933, "label": "Lac de Warfaaz"}, {"lat": 50.5333, "lng": 5.8203, "label": "Château de Franchimont"}, {"lat": 50.4794, "lng": 5.7136, "label": "Grottes de Remouchamps"}, {"lat": 50.3947, "lng": 5.9308, "label": "Stavelot"}, {"lat": 50.4922, "lng": 5.8628, "label": "Cíl: Spa"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.4922,5.8628&destination=50.4922,5.8628&travelmode=driving&waypoints=50.5006,5.8933%7C50.5333,5.8203%7C50.4794,5.7136%7C50.3947,5.9308', 'https://commons.wikimedia.org/wiki/Special:FilePath/Spa%20Pouhon-Pierre-Le-Grand%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Spa%20Pouhon-Pierre-Le-Grand%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Spa%20Lac%20Warfaaz%20R01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/0%20Theux%20-%20Ch%C3%A2teau%20de%20Franchimont%20(3).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Grottes%20de%20Remouchamps%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Abbaye%20de%20Stavelot%2003.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Spa%20Pouhon%20PLG%20R01.jpg"}'::text[], '{"Spa – Pouhon Pierre le Grand","Lac de Warfaaz","Château de Franchimont","Grottes de Remouchamps","Stavelot – opatství","Restaurace: Brasserie du Grand Maur (Spa)"}'::text[], '{"BE"}'::text[], false, 3120, 'approved');

  -- Hautes Fagnes – Signal de Botrange a Robertville
  delete from public.routes where name = 'Hautes Fagnes – Signal de Botrange a Robertville' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Hautes Fagnes – Signal de Botrange a Robertville', 'Okruh po střeše Belgie vede otevřenými vřesovišti a rašeliništi národního parku Hautes Fagnes, kde silnice běží po náhorní plošině s výhledy na desítky kilometrů. Z Malmedy vystoupáte k Baraque Michel a na Signal de Botrange (694 m), nejvyšší bod země, a přes hráz přehrady na Vesdre u Eupenu se vrátíte kolem jezera Robertville a pohádkového hradu Reinhardstein. Kombinace rychlých přehledných úseků nahoře a lesních serpentin v údolí Warche je jízdně velmi pestrá. Nahoře bývá větrno, chladněji a rychlé změny počasí – přibalte vrstvu navíc i v létě. Nejkrásněji je tu na přelomu léta, kdy vřesoviště fialově kvetou.', 'loop', 90, 150, 'easy',
     '[{"lat": 50.4258, "lng": 6.0281, "label": "Start: Malmedy"}, {"lat": 50.5203, "lng": 6.0631, "label": "Baraque Michel"}, {"lat": 50.5017, "lng": 6.0939, "label": "Signal de Botrange"}, {"lat": 50.5989, "lng": 6.0761, "label": "Barrage de la Vesdre (Eupen)"}, {"lat": 50.4569, "lng": 6.1114, "label": "Lac de Robertville"}, {"lat": 50.4433, "lng": 6.1114, "label": "Château de Reinhardstein"}, {"lat": 50.4258, "lng": 6.0281, "label": "Cíl: Malmedy"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.4258,6.0281&destination=50.4258,6.0281&travelmode=driving&waypoints=50.5203,6.0631%7C50.5017,6.0939%7C50.5989,6.0761%7C50.4569,6.1114%7C50.4433,6.1114', 'https://commons.wikimedia.org/wiki/Special:FilePath/Signal%20de%20Botrange%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cath%C3%A9drale%20de%20Malmedy.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Baraque%20Michel,%20restaurant%20Baraque%20Michel%20foto3%202011-06-04%2013.19.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Signal%20de%20Botrange%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Wesertalsperre%20Eupen.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Robertville%20JPG01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Robertville%20-%20Ch%C3%A2teau%20de%20Reinhardstein.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cath%C3%A9drale%20de%20Malmedy.jpg"}'::text[], '{"Malmedy – katedrála","Baraque Michel","Signal de Botrange","Barrage de la Vesdre (Eupen)","Lac de Robertville","Château de Reinhardstein","Restaurace: Plein Vent (Bévercé u Malmedy)"}'::text[], '{"BE"}'::text[], false, 3130, 'approved');

  -- Údolí Mázy – Namur, Dinant a Freÿr
  delete from public.routes where name = 'Údolí Mázy – Namur, Dinant a Freÿr' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Údolí Mázy – Namur, Dinant a Freÿr', 'Pohodová jízda nejkrásnějším úsekem údolí Mázy (Meuse), kde řeku svírají vápencové stěny a silnice N92 a N96 kopírují každý její záhyb těsně u hladiny. Z citadely v Namuru pojedete přes vodní zahrady v Annevoie do Dinantu, města rodáka Adolpha Saxe s citadelou na skále, a dál kolem jehly Rocher Bayard k renesančnímu zámku Freÿr. Závěr obstará pohádkový hrad Vêves a návrat zvlněnou krajinou Condroz. Provoz u řeky je mírný, povrch výborný, jen o letních víkendech počítejte s turisty v Dinantu. Ideální trasa na první seznámení s Valonskem.', 'loop', 110, 165, 'easy',
     '[{"lat": 50.4633, "lng": 4.8650, "label": "Start: Namur"}, {"lat": 50.3444, "lng": 4.8506, "label": "Jardins d''Annevoie"}, {"lat": 50.2606, "lng": 4.9122, "label": "Dinant"}, {"lat": 50.2508, "lng": 4.9086, "label": "Rocher Bayard"}, {"lat": 50.2222, "lng": 4.8894, "label": "Château de Freÿr"}, {"lat": 50.2258, "lng": 5.0072, "label": "Celles – Château de Vêves"}, {"lat": 50.4633, "lng": 4.8650, "label": "Cíl: Namur"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.4633,4.8650&destination=50.4633,4.8650&travelmode=driving&waypoints=50.3444,4.8506%7C50.2606,4.9122%7C50.2508,4.9086%7C50.2222,4.8894%7C50.2258,5.0072', 'https://commons.wikimedia.org/wiki/Special:FilePath/Dinant%20Coll%C3%A9giale%20Notre%20Dame%2001.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/La%20Citadelle%20de%20Namur.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Les%20jardins%20d''Annevoie%20-%20Le%20petit%20canal.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Dinant%20Coll%C3%A9giale%20Notre%20Dame%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Dinant%20Coll%C3%A9giale%20Notre%20Dame%2001.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/RocherBayardDinant.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Ch%C3%A2teau%20de%20Fre%C3%BFr%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Celles%20(Houyet)%20-%20Ch%C3%A2teau%20de%20V%C3%AAves%20(1).jpg"}'::text[], '{"Citadela Namur","Jardins d''Annevoie","Dinant – Collégiale a citadela","Restaurace: La Broche (Dinant)","Rocher Bayard","Château de Freÿr","Château de Vêves"}'::text[], '{"BE"}'::text[], false, 3140, 'approved');

  -- Flandry – Brugy, Damme a pobřeží
  delete from public.routes where name = 'Flandry – Brugy, Damme a pobřeží' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Flandry – Brugy, Damme a pobřeží', 'Rovinatý, ale nesmírně malebný okruh západními Flandrami: středověké Brugy se zvonicí a kanály, alej podél kanálu do hanzovního Damme, slaniska rezervace Zwin u hranice s Nizozemskem a návrat po pobřeží Severního moře přes belle époque lázně De Haan do Ostende. Jezdí se po úzkých silničkách po korunách hrází, mezi poldery a řadami topolů, kde je zážitkem samotné světlo a vítr od moře. Technicky nenáročné, ideální i pro spolujezdce; pozor na boční vítr na hrázích, cyklisty a koleje pobřežní tramvaje. Nejlepší od dubna do září, ryby a hranolky u moře jsou povinnost.', 'loop', 85, 150, 'easy',
     '[{"lat": 51.2093, "lng": 3.2247, "label": "Start: Brugy"}, {"lat": 51.2511, "lng": 3.2814, "label": "Damme"}, {"lat": 51.3583, "lng": 3.3592, "label": "Zwin (Knokke-Heist)"}, {"lat": 51.2725, "lng": 3.0347, "label": "De Haan"}, {"lat": 51.2326, "lng": 2.9126, "label": "Oostende"}, {"lat": 51.2093, "lng": 3.2247, "label": "Cíl: Brugy"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=51.2093,3.2247&destination=51.2093,3.2247&travelmode=driving&waypoints=51.2511,3.2814%7C51.3583,3.3592%7C51.2725,3.0347%7C51.2326,2.9126', 'https://commons.wikimedia.org/wiki/Special:FilePath/Brugge-CanalRozenhoedkaai.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Brugge-CanalRozenhoedkaai.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Brauerei%20De%20Halve%20Maan%20(Brouwerij%20De%20Halve%20Maan)%20in%20Br%C3%BCgge,%20Belgien%20-%20Eingangsbereich.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Damme%20town%20hall,%20Belgium.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/20110522%20Zwin%20(7).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/De%20Haan%20tramstation.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Oostende%20Albert%20I%20Promenade%20R01.jpg"}'::text[], '{"Brugy – Rozenhoedkaai a Belfort","Pivovar De Halve Maan (Brugy)","Damme","Přírodní rezervace Zwin","De Haan – belle époque","Oostende – Albert I. promenáda"}'::text[], '{"BE"}'::text[], false, 3150, 'approved');

  -- Gent a Flanderské Ardeny – Koppenberg a Muur
  delete from public.routes where name = 'Gent a Flanderské Ardeny – Koppenberg a Muur' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Gent a Flanderské Ardeny – Koppenberg a Muur', 'Okruh z Gentu do kopcovitého jihu Východních Flander, kterému se říká Flanderské Ardeny – kraj proslavený jarní cyklistickou klasikou Kolem Flander. Po prohlídce hradu Gravensteen zamíříte podél řeky Šeldy do Oudenaarde s nejkrásnější gotickou radnicí Belgie a pak na legendární kostkované stěny Koppenberg, Oude Kwaremont a Muur van Geraardsbergen, které na motorce vychutnáte úplně jinak než cyklisté. Mezi kopci se jezdí po úzkých silničkách mezi poli a chmelnicemi s výhledy do kraje. Na kostkách jeďte plynule a opatrně, za mokra jsou zrádné jak led. Nejhezčí od jara do podzimu; v dubnu o víkendu závodů kraj ožívá.', 'loop', 120, 180, 'medium',
     '[{"lat": 51.0543, "lng": 3.7174, "label": "Start: Gent"}, {"lat": 50.8442, "lng": 3.6072, "label": "Oudenaarde"}, {"lat": 50.8256, "lng": 3.5744, "label": "Koppenberg"}, {"lat": 50.7789, "lng": 3.5219, "label": "Oude Kwaremont"}, {"lat": 50.7658, "lng": 3.8811, "label": "Geraardsbergen"}, {"lat": 51.0543, "lng": 3.7174, "label": "Cíl: Gent"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=51.0543,3.7174&destination=51.0543,3.7174&travelmode=driving&waypoints=50.8442,3.6072%7C50.8256,3.5744%7C50.7789,3.5219%7C50.7658,3.8811', 'https://commons.wikimedia.org/wiki/Special:FilePath/The%20Gravensteen%20Castle%20-%20Ghent,%20Belgium%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Gravensteen%20Castle%20-%20Ghent,%20Belgium%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Oudenaarde%20(East%20Flanders,%20Belgium)%20late%20Gothic%20town%20hall%20and%20belfry%20tower.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Monument%20Markt%201%20(stadhuis)%20Oudenaarde.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Koppenberg%20cobbles.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/De%20Sint-Amanduskerk%20gezien%20van%20op%20de%20Oude%20Kwaremont%20-%202020.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Muur%20van%20Geraardsbergen%20116.jpg"}'::text[], '{"Gravensteen (Gent)","Oudenaarde – radnice","Restaurace: Margaretha''s (Oudenaarde)","Koppenberg","Oude Kwaremont","Muur van Geraardsbergen (Kapelmuur)"}'::text[], '{"BE"}'::text[], false, 3160, 'approved');

  -- Hageland – Leuven, Scherpenheuvel a Averbode
  delete from public.routes where name = 'Hageland – Leuven, Scherpenheuvel a Averbode' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Hageland – Leuven, Scherpenheuvel a Averbode', 'Pohodový okruh vinařským Hagelandem, nejstarším vinařským krajem Flander mezi Leuvenem a Diestem. Od nejzdobnější gotické radnice světa v Leuvenu pojedete kolem opatství Park přes železité vrchy s vinicemi k barokní poutní bazilice ve Scherpenheuvel a bílému opatství Averbode uprostřed borových lesů. Závěr patří Diestu s tichým bekinážním dvorem na seznamu UNESCO. Silničky mezi ovocnými sady a vinicemi jsou úzké, zvlněné a téměř prázdné – ideální na klidné tempo a časté zastávky. Trasa je nenáročná a krásná hlavně v dubnu, kdy kvetou sady, a na podzim při vinobraní.', 'loop', 95, 150, 'easy',
     '[{"lat": 50.8792, "lng": 4.7009, "label": "Start: Leuven"}, {"lat": 50.8631, "lng": 4.7181, "label": "Opatství Park"}, {"lat": 50.9800, "lng": 4.9772, "label": "Scherpenheuvel"}, {"lat": 51.0236, "lng": 4.9808, "label": "Averbode"}, {"lat": 50.9886, "lng": 5.0508, "label": "Diest"}, {"lat": 50.8792, "lng": 4.7009, "label": "Cíl: Leuven"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.8792,4.7009&destination=50.8792,4.7009&travelmode=driving&waypoints=50.8631,4.7181%7C50.9800,4.9772%7C51.0236,4.9808%7C50.9886,5.0508', 'https://commons.wikimedia.org/wiki/Special:FilePath/Leuven,%20stadhuis.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Leuven,%20stadhuis.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Abdij%20van%20''t%20Park.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Onze-Lieve-Vrouwebasiliek%20in%20Scherpenheuvel.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Averbode%20Abdij%20R01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Diest-begijnhof.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Stadhuis%20Leuven.JPG"}'::text[], '{"Leuven – radnice","Opatství Park (Heverlee)","Bazilika Scherpenheuvel","Opatství Averbode","Diest – bekináž","Restaurace: Zarza (Leuven)"}'::text[], '{"BE"}'::text[], false, 3170, 'approved');

  -- Condroz – Huy, Modave a zámek Jehay
  delete from public.routes where name = 'Condroz – Huy, Modave a zámek Jehay' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Condroz – Huy, Modave a zámek Jehay', 'Objevitelský okruh krajem Condroz – vlnící se krajinou vápencových hřbetů a úrodných údolí mezi Mázou a Ardenami, kterou turisté zatím míjejí. Z Huy s mohutnou citadelou nad řekou zamíříte k šachovnicovému zámku Jehay, pak do údolí říčky Hoyoux k baroknímu zámku Modave na skále a přes tiché vesnice z modrošedého kamene až do Crupet, jedné z nejkrásnějších vesnic Valonska. Silnice druhé a třetí třídy se tu neustále vlní nahoru a dolů, s rytmem dlouhých zatáček mezi poli a lesíky. Provoz minimální, povrch většinou dobrý; pozor na zemědělskou techniku a bláto u polí po dešti. Krásné od jara do zlatého podzimu.', 'loop', 100, 160, 'medium',
     '[{"lat": 50.5186, "lng": 5.2397, "label": "Start: Huy"}, {"lat": 50.5644, "lng": 5.2914, "label": "Château de Jehay"}, {"lat": 50.4453, "lng": 5.2958, "label": "Château de Modave"}, {"lat": 50.3494, "lng": 4.9528, "label": "Crupet"}, {"lat": 50.4894, "lng": 5.0964, "label": "Andenne"}, {"lat": 50.5186, "lng": 5.2397, "label": "Cíl: Huy"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.5186,5.2397&destination=50.5186,5.2397&travelmode=driving&waypoints=50.5644,5.2914%7C50.4453,5.2958%7C50.3494,4.9528%7C50.4894,5.0964', 'https://commons.wikimedia.org/wiki/Special:FilePath/Citadelle%20de%20Huy%20006.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Citadelle%20de%20Huy%20006.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Coll%C3%A9giale%20Notre-Dame,%20Huy-1130.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/0%20Jehay%20-%20Ch%C3%A2teau%20(1).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Modave-Ch%C3%A2teau%20de%20Modave%20(4).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Crupet%20Castle%20donjon%2002.JPG"}'::text[], '{"Huy – citadela a kolegiáta","Restaurace: Li Cwerneu (Huy)","Château de Jehay","Château de Modave","Crupet – donjon"}'::text[], '{"BE"}'::text[], false, 3180, 'approved');

  -- Gaume – opatství Orval a Torgny
  delete from public.routes where name = 'Gaume – opatství Orval a Torgny' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Gaume – opatství Orval a Torgny', 'Okruh nejjižnějším cípem Belgie, slunečnou Gaume, které se pro mírné klima říká belgická Provence. Z Virtonu vyrazíte na sever k Semois u Chiny, pak k legendárnímu trapistickému opatství Orval, kde se vaří jedno z nejceněnějších piv světa, a zpět přes vinařskou vesničku Torgny s okrovými fasádami a zříceninu Montquintin na kopci. Silnice se vlní mezi loukami, lesíky a vápencovými hřbety, provoz je minimální a tempo si diktujete sami. Trasa je nenáročná a krásná od jara do pozdního podzimu. Pivo Orval si kupte s sebou – řízení a degustace počká na večer.', 'loop', 105, 165, 'easy',
     '[{"lat": 49.5675, "lng": 5.5325, "label": "Start: Virton"}, {"lat": 49.7369, "lng": 5.3411, "label": "Chiny"}, {"lat": 49.6389, "lng": 5.3494, "label": "Opatství Orval"}, {"lat": 49.5064, "lng": 5.4772, "label": "Torgny"}, {"lat": 49.5300, "lng": 5.4750, "label": "Montquintin"}, {"lat": 49.5675, "lng": 5.5325, "label": "Cíl: Virton"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.5675,5.5325&destination=49.5675,5.5325&travelmode=driving&waypoints=49.7369,5.3411%7C49.6389,5.3494%7C49.5064,5.4772%7C49.5300,5.4750', 'https://commons.wikimedia.org/wiki/Special:FilePath/Abbaye%20d''Orval%20-%20Ruins%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/P1090022%20Chiny.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Abbaye%20d''Orval%20-%20Ruins%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/BE-LX-Orval%20Abbaye%20hostellerie.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Torgny%20-%20Clos%20de%20l''Epinette.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Montquintin%20JPG00.JPG"}'::text[], '{"Chiny – brána Semois","Opatství Orval","Restaurace: À l''Ange Gardien (Orval)","Torgny","Montquintin – zřícenina"}'::text[], '{"BE"}'::text[], false, 3190, 'approved');

  -- Údolí Ourthe – Le Hérou, Nisramont a Achouffe
  delete from public.routes where name = 'Údolí Ourthe – Le Hérou, Nisramont a Achouffe' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Údolí Ourthe – Le Hérou, Nisramont a Achouffe', 'Okruh divokým srdcem Arden kolem Houffalize, mekky evropských bikerů na břehu Ourthe. Čeká vás pivovar Achouffe s ikonickým skřítkem, stoupání na Baraque de Fraiture – třetí nejvyšší bod Belgie, skalní vyhlídka Le Hérou nad sevřenými meandry řeky a hráz přehrady Nisramont, kde se obě Ourthe potkávají v jednom jezeře. Silnice se střídají od rychlých hřebenových pasáží po utažené serpentiny do údolí; asfalt je vesměs výborný. V lesích pozor na zvěř za soumraku a vlhké úseky ve stínu. Nejkrásněji je tu v říjnu, kdy ardenské lesy hrají všemi barvami.', 'loop', 85, 145, 'medium',
     '[{"lat": 50.1325, "lng": 5.7897, "label": "Start: Houffalize"}, {"lat": 50.1614, "lng": 5.7758, "label": "Achouffe"}, {"lat": 50.2489, "lng": 5.7364, "label": "Baraque de Fraiture"}, {"lat": 50.1592, "lng": 5.6733, "label": "Nadrin – Le Hérou"}, {"lat": 50.1300, "lng": 5.6903, "label": "Barrage de Nisramont"}, {"lat": 50.1325, "lng": 5.7897, "label": "Cíl: Houffalize"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=50.1325,5.7897&destination=50.1325,5.7897&travelmode=driving&waypoints=50.1614,5.7758%7C50.2489,5.7364%7C50.1592,5.6733%7C50.1300,5.6903', 'https://commons.wikimedia.org/wiki/Special:FilePath/Le%20Herou01.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Houffalize%200011.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20van%20Achouffe.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20van%20Achouffe.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Skipiste%20Baraque%20Fraiture.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Le%20Herou01.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/0%20Nisramont%20-%20Barrage%20(1).JPG"}'::text[], '{"Houffalize","Pivovar Achouffe (La Chouffe)","Restaurace: La Petite Fontaine (Achouffe)","Baraque de Fraiture","Le Hérou (Nadrin)","Barrage de Nisramont"}'::text[], '{"BE"}'::text[], false, 3200, 'approved');

